package com.restaurant.management.controller;

import com.restaurant.management.entity.*; import com.restaurant.management.enums.*; import com.restaurant.management.repository.*; import com.restaurant.management.security.RestaurantUserPrincipal;
import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.test.annotation.DirtiesContext; import org.springframework.test.context.*; import org.springframework.test.web.servlet.MockMvc; import org.testcontainers.containers.PostgreSQLContainer; import org.testcontainers.junit.jupiter.*;
import java.math.BigDecimal; import java.time.*; import java.util.*; import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.assertThat; import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest @AutoConfigureMockMvc @Testcontainers(disabledWithoutDocker=true) @DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
class TableauBordIntegrationTest {
 static final AtomicInteger TABLES=new AtomicInteger(80000);
 @Container static final PostgreSQLContainer<?> PG=new PostgreSQLContainer<>("postgres:17-alpine").withDatabaseName("restaurant_dashboard_integration").withUsername("test").withPassword(UUID.randomUUID().toString());
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.url",PG::getJdbcUrl);r.add("spring.datasource.username",PG::getUsername);r.add("spring.datasource.password",PG::getPassword);r.add("spring.jpa.hibernate.ddl-auto",()->"validate");r.add("spring.flyway.enabled",()->"true");r.add("springdoc.api-docs.enabled",()->"false");r.add("springdoc.swagger-ui.enabled",()->"false");}
 @Autowired MockMvc mvc; @Autowired EmployeRepository employes; @Autowired UtilisateurRepository utilisateurs; @Autowired RoleRepository roles; @Autowired TableRestaurantRepository tables; @Autowired ClientRepository clients; @Autowired CategorieRepository categories; @Autowired ProduitRepository produits; @Autowired CommandeRepository commandes; @Autowired PaiementRepository paiements; @Autowired ReservationRepository reservations; @Autowired IngredientRepository ingredients; @Autowired FournisseurRepository fournisseurs; @Autowired AchatRepository achats; @Autowired JournalActiviteRepository journaux;

 @Test void permissionsSontCorrectementLimitees(){assertThat(roles.findWithPermissionsByNom(NomRole.GERANT).orElseThrow().getPermissions()).extracting(Permission::getNom).contains(NomPermission.TABLEAU_BORD_CONSULTER,NomPermission.TABLEAU_BORD_FINANCIER_CONSULTER,NomPermission.JOURNAL_ACTIVITE_CONSULTER);assertThat(roles.findWithPermissionsByNom(NomRole.SERVEUR).orElseThrow().getPermissions()).extracting(Permission::getNom).contains(NomPermission.TABLEAU_BORD_CONSULTER).doesNotContain(NomPermission.TABLEAU_BORD_FINANCIER_CONSULTER);}
 @Test void calculsOperationnelsEtFinanciersSontAgregesEnBase() throws Exception {Jeu j=jeu();String dates=datesAujourdhui();mvc.perform(get("/api/tableau-de-bord/operations?"+dates).with(user(j.gerant()))).andExpect(status().isOk()).andExpect(jsonPath("$.nombreCommandes").value(1)).andExpect(jsonPath("$.nombreTablesDisponibles").value(1)).andExpect(jsonPath("$.commandesParEtat[?(@.libelle == 'PRETE')].valeur").value(1)).andExpect(jsonPath("$.produitsLesPlusVendus[0].produitId").value(j.produit().getId())).andExpect(jsonPath("$.produitsLesPlusVendus[0].quantite").value(2)).andExpect(jsonPath("$.reservations[?(@.libelle == 'EN_ATTENTE')].valeur").value(1)).andExpect(jsonPath("$.stocksFaibles[?(@.ingredientId == %d)]".formatted(j.ingredient().getId())).exists());mvc.perform(get("/api/tableau-de-bord/finances?"+dates).with(user(j.gerant()))).andExpect(status().isOk()).andExpect(jsonPath("$.chiffreAffaires").value(20.00)).andExpect(jsonPath("$.paiementsParMode[?(@.libelle == 'ESPECES')].valeur").value(12.00)).andExpect(jsonPath("$.paiementsParMode[?(@.libelle == 'CARTE')].valeur").value(8.00)).andExpect(jsonPath("$.depensesAchat").value(15.00));}
 @Test void filtresDePeriodeEtLimiteSontValides() throws Exception {Utilisateur u=utilisateur();RestaurantUserPrincipal p=gerant(u.getId());LocalDate demain=LocalDate.now(ZoneOffset.UTC).plusDays(1);mvc.perform(get("/api/tableau-de-bord/operations").param("debut",demain.toString()).param("fin",demain.toString()).with(user(p))).andExpect(status().isOk()).andExpect(jsonPath("$.nombreCommandes").value(0));mvc.perform(get("/api/tableau-de-bord/operations?debut=2025-01-01&fin=2024-12-31").with(user(p))).andExpect(status().isConflict());mvc.perform(get("/api/tableau-de-bord/operations?debut=2024-01-01&fin=2026-01-02").with(user(p))).andExpect(status().isConflict());mvc.perform(get("/api/tableau-de-bord/operations?debut=invalide").with(user(p))).andExpect(status().isBadRequest());}
 @Test void financesSontReserveesAuxRolesGerantEtAdministrateur() throws Exception {mvc.perform(get("/api/tableau-de-bord/finances")).andExpect(status().isUnauthorized());mvc.perform(get("/api/tableau-de-bord/finances").with(user(principal(-1L,"ROLE_SERVEUR","TABLEAU_BORD_CONSULTER","TABLEAU_BORD_FINANCIER_CONSULTER")))).andExpect(status().isForbidden());mvc.perform(get("/api/tableau-de-bord/operations").with(user(principal(-1L,"ROLE_SERVEUR","TABLEAU_BORD_CONSULTER")))).andExpect(status().isOk());}
 @Test void journalEstPagineFiltreEtNExposePasLesDetailsLibres() throws Exception {Utilisateur u=utilisateur();JournalActivite entree=new JournalActivite(u,"TEST_AUDIT","TEST",u.getId().toString(),ResultatActivite.SUCCES,UUID.randomUUID());entree.setDetails("password=ne-doit-jamais-sortir");entree.setAdresseIp("127.0.0.1");journaux.saveAndFlush(entree);RestaurantUserPrincipal auditeur=gerant(u.getId());mvc.perform(get("/api/tableau-de-bord/journal").param("action","TEST_AUDIT").param("taille","5").with(user(auditeur))).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(1)).andExpect(jsonPath("$.contenu[0].action").value("TEST_AUDIT")).andExpect(jsonPath("$.contenu[0].utilisateurId").value(u.getId())).andExpect(jsonPath("$.contenu[0].utilisateurNom").value(u.getEmploye().getPrenom()+" "+u.getEmploye().getNom())).andExpect(jsonPath("$.contenu[0].details").doesNotExist()).andExpect(jsonPath("$.contenu[0].adresseIp").doesNotExist());mvc.perform(get("/api/tableau-de-bord/journal/utilisateurs").with(user(auditeur))).andExpect(status().isOk()).andExpect(jsonPath("$[?(@.id == %d)].email".formatted(u.getId())).value(u.getEmail()));mvc.perform(get("/api/tableau-de-bord/journal").with(user(principal(u.getId(),"ROLE_SERVEUR","TABLEAU_BORD_CONSULTER")))).andExpect(status().isForbidden());mvc.perform(get("/api/tableau-de-bord/journal/utilisateurs").with(user(principal(u.getId(),"ROLE_SERVEUR","UTILISATEUR_CONSULTER")))).andExpect(status().isForbidden());}

 private Jeu jeu(){Utilisateur u=utilisateur();TableRestaurant occupee=tables.saveAndFlush(new TableRestaurant(TABLES.incrementAndGet(),4));tables.saveAndFlush(new TableRestaurant(TABLES.incrementAndGet(),4));TableRestaurant reservee=tables.saveAndFlush(new TableRestaurant(TABLES.incrementAndGet(),4));TableRestaurant horsService=new TableRestaurant(TABLES.incrementAndGet(),4);horsService.setActif(false);tables.saveAndFlush(horsService);Client client=clients.saveAndFlush(new Client("Client","Dashboard",null,null));Categorie cat=categories.saveAndFlush(new Categorie("Cat-"+UUID.randomUUID(),null));Produit produit=produits.saveAndFlush(new Produit("Produit-"+UUID.randomUUID(),null,new BigDecimal("10.00"),cat));Commande c=new Commande("CMD-DASH-"+UUID.randomUUID().toString().substring(0,8),occupee,client,u);c.ajouterLigne(produit,2,produit.getPrix(),null);c.confirmer();c.demarrerPreparation();c.marquerPrete();c=commandes.saveAndFlush(c);paiements.saveAndFlush(new Paiement(c,u,UUID.randomUUID(),new BigDecimal("12.00"),ModePaiement.ESPECES));paiements.saveAndFlush(new Paiement(c,u,UUID.randomUUID(),new BigDecimal("8.00"),ModePaiement.CARTE));reservations.saveAndFlush(new Reservation("RES-DASH-"+UUID.randomUUID().toString().substring(0,8),reservee,client,u,2,Instant.now(),null));Ingredient i=ingredients.saveAndFlush(new Ingredient("Ing-"+UUID.randomUUID(),UniteMesure.KILOGRAMME,new BigDecimal("5")));Fournisseur f=fournisseurs.saveAndFlush(new Fournisseur("Four-"+UUID.randomUUID(),null,null,null));Achat a=new Achat("ACH-DASH-"+UUID.randomUUID().toString().substring(0,8),f,u);a.ajouterLigne(i,new BigDecimal("3"),new BigDecimal("5"));a.commander();achats.saveAndFlush(a);return new Jeu(produit,i,gerant(u.getId()));}
 private Utilisateur utilisateur(){String s=UUID.randomUUID().toString().substring(0,8);Employe e=employes.saveAndFlush(new Employe("DB-"+s,"Dash",s,"Dashboard",LocalDate.now()));return utilisateurs.saveAndFlush(new Utilisateur("dash-"+s+"@example.com","$2a$12$test",e));}
 private RestaurantUserPrincipal gerant(Long id){return principal(id,"ROLE_GERANT","TABLEAU_BORD_CONSULTER","TABLEAU_BORD_FINANCIER_CONSULTER","JOURNAL_ACTIVITE_CONSULTER");}
 private RestaurantUserPrincipal principal(Long id,String...a){return new RestaurantUserPrincipal(id,"x@x.test",null,true,Arrays.stream(a).map(SimpleGrantedAuthority::new).toList());}
 private String datesAujourdhui(){String d=LocalDate.now(ZoneOffset.UTC).toString();return "debut="+d+"&fin="+d;}
 private record Jeu(Produit produit,Ingredient ingredient,RestaurantUserPrincipal gerant){}
}
